import{_ as i,c as n,o as a,ah as t}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"I Ching Basics","description":"I Ching Basics，整理自 App 的免費易經學習文檔。","frontmatter":{"title":"I Ching Basics","description":"I Ching Basics，整理自 App 的免費易經學習文檔。"},"headers":[],"relativePath":"en/articles/basics/index.md","filePath":"en/articles/basics/index.md"}'),r={name:"en/articles/basics/index.md"};function l(s,e,o,h,g,d){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="i-ching-basics-brief" tabindex="-1">I Ching Basics (Brief) <a class="header-anchor" href="#i-ching-basics-brief" aria-label="Permalink to “I Ching Basics (Brief)”">​</a></h1><ul><li>Hexagram: six lines; upper trigram (top 3) and lower trigram (bottom 3).</li><li>Line: still lines — yin (broken) / yang (solid) — are drawn with colored strokes whose palette follows the trigrams’ attributes (Heaven/Earth/Thunder/Wind/Water/Fire/Mountain/Lake); moving lines — old yin / old yang — are marked with a trailing cross (×) for old yin and a trailing circle (○) for old yang.</li><li>Upper/Lower Trigrams: every hexagram consists of two trigrams — the top three lines form the upper trigram (also called the outer or “use” trigram), and the bottom three lines form the lower trigram (also called the inner or “body” trigram).</li><li>Being in Position (yin/yang suitability by place): counting from the bottom, the six places are 1st (Initial), 2nd, 3rd, 4th, 5th, and Top. Places 1/3/5 are yang‑places; places 2/4/Top are yin‑places. A yang line in a yang‑place or a yin line in a yin‑place is “in position” (de‑wei); otherwise it is “not in position”.</li><li>Original/Changed: changing lines flip to form the changed hexagram. Read Original as body, Changed as application.</li></ul><h3 id="interpreting-changes-by-number-of-moving-lines" tabindex="-1">Interpreting Changes (by number of moving lines) <a class="header-anchor" href="#interpreting-changes-by-number-of-moving-lines" aria-label="Permalink to “Interpreting Changes (by number of moving lines)”">​</a></h3><ul><li>One moving line: read the line text of that moving line in the Original hexagram.</li><li>Two moving lines: read the two moving lines’ texts in the Original; the higher line takes precedence.</li><li>Three moving lines: read the Judgements of Original and Changed together (treat Original as “zhen/ti”—the body, and Changed as “hui/yong”—the application/adjustment).</li><li>Four moving lines: read the two unchanging lines’ texts in the Changed hexagram; the lower one takes precedence.</li><li>Five moving lines: read the only unchanging line’s text in the Changed hexagram.</li><li>Six moving lines: read the Judgement of the Changed hexagram; for Qian (乾) and Kun (坤), read “Use of Nine” / “Use of Six”.</li><li>Texts: the app includes bilingual Judgement/Lines/Image with script switching.</li></ul>',4)])])}const p=i(r,[["render",l]]);export{m as __pageData,p as default};
